(()=>{const fmt=c=>(typeof Shopify!='undefined'&&Shopify.formatMoney)?Shopify.formatMoney(c):'$'+(c/100).toFixed(2);const root=window.Shopify?.routes?.root||'/';const AJ='application/json',H={'Content-Type':AJ,Accept:AJ};function refresh(){['cart:refresh','cart:updated','shiprocket:cart:refresh'].forEach(n=>{document.documentElement.dispatchEvent(new CustomEvent(n,{bubbles:!0}));document.dispatchEvent(new CustomEvent(n,{bubbles:!0}));window.dispatchEvent(new CustomEvent(n))});const d=document.querySelector('cart-drawer');if(d&&typeof d.renderContents=='function'){fetch(root+'?sections=cart-drawer,cart-icon-bubble').then(r=>r.json()).then(s=>{d.renderContents({sections:s});if(typeof d.open=='function')d.open()}).catch(()=>{})}else if(window.location.pathname.includes('/cart')){window.location.reload()}}let splitting=!1;async function splitCart(){if(splitting)return;let rules=window.__btRules;if(!rules||!rules.length){try{const cached=localStorage.getItem('__btRules');if(cached)rules=JSON.parse(cached)}catch(e){}}if(!rules||!rules.length)return;try{const r=await fetch(root+'cart.js?_bt_internal=1');if(!r.ok)return;const cart=await r.json();if(!cart?.items?.length)return;const pMap=new Map();for(const it of cart.items){if(it.properties?._bundle==='fbt_companion')continue;const p=String(it.product_id),l=pMap.get(p)||[];l.push(it);pMap.set(p,l)}let changed=!1;for(const[pid,items]of pMap.entries()){const mRules=rules.filter(x=>{if(!x.active||!x.tiers?.length)return!1;const g=String(x.targetGid||'');if(x.targetType==='PRODUCT'&&g.includes(pid))return!0;if(x.targetType==='COLLECTION'){const cp=(x.collectionProductIds||[]).map(String);if(cp.includes(pid))return!0}return!1});if(!mRules.length)continue;const tiers=[];mRules.forEach(x=>{(x.tiers||[]).forEach(t=>{if(t.minQuantity>0&&t.discountPercent>0)tiers.push(t)})});if(!tiers.length)continue;const tot=items.reduce((s,i)=>s+i.quantity,0);let bTier=null;for(const t of tiers){if(tot>=t.minQuantity&&(!bTier||t.discountPercent>bTier.discountPercent)){bTier=t}}if(!bTier){const dIt=items.find(i=>i.properties?._tier_split==='discounted');if(dIt){splitting=!0;await fetch(root+'cart/change.js?_bt_internal=1',{method:'POST',headers:H,body:JSON.stringify({id:dIt.key,quantity:dIt.quantity,properties:{_tier_split:'regular'}})});changed=!0}continue}const eq=bTier.minQuantity,ex=tot-eq,lbl=bTier.label||`Buy ${eq} - Save ${bTier.discountPercent}%`;const dIt=items.find(i=>i.properties?._tier_split==='discounted'),rIt=items.find(i=>i.properties?._tier_split==='regular'||(!i.properties?._tier_split&&i!==dIt));if(items.length===1){const s=items[0];if(s.quantity===eq){if(s.properties?._tier_split!=='discounted'||s.properties?.Discount!==lbl){splitting=!0;await fetch(root+'cart/change.js?_bt_internal=1',{method:'POST',headers:H,body:JSON.stringify({id:s.key,quantity:eq,properties:{_tier_split:'discounted',Discount:lbl}})});changed=!0}}else if(s.quantity>eq){splitting=!0;await fetch(root+'cart/change.js?_bt_internal=1',{method:'POST',headers:H,body:JSON.stringify({id:s.key,quantity:eq,properties:{_tier_split:'discounted',Discount:lbl}})});await fetch(root+'cart/add.js?_bt_internal=1',{method:'POST',headers:H,body:JSON.stringify({items:[{id:s.variant_id,quantity:ex,properties:{_tier_split:'regular'}}]})});changed=!0}}else{const dQty=dIt?dIt.quantity:0,rQty=rIt?rIt.quantity:0;if(dQty===eq&&rQty===ex&&dIt?.properties?.Discount===lbl){continue}splitting=!0;if(dIt){await fetch(root+'cart/change.js?_bt_internal=1',{method:'POST',headers:H,body:JSON.stringify({id:dIt.key,quantity:eq,properties:{_tier_split:'discounted',Discount:lbl}})} )}if(ex>0){if(rIt){await fetch(root+'cart/change.js?_bt_internal=1',{method:'POST',headers:H,body:JSON.stringify({id:rIt.key,quantity:ex,properties:{_tier_split:'regular'}})} )}else{const vId=dIt?dIt.variant_id:items[0].variant_id;await fetch(root+'cart/add.js?_bt_internal=1',{method:'POST',headers:H,body:JSON.stringify({items:[{id:vId,quantity:ex,properties:{_tier_split:'regular'}}]})})}}else if(rIt){await fetch(root+'cart/change.js?_bt_internal=1',{method:'POST',headers:H,body:JSON.stringify({id:rIt.key,quantity:0})})}changed=!0}}if(changed){refresh();setTimeout(()=>{splitting=!1},800)}else{splitting=!1}}catch(e){splitting=!1}}let sTimer=null;function scheduleSplit(){if(sTimer)clearTimeout(sTimer);sTimer=setTimeout(splitCart,250)}if(!window.__btFetchPatched){window.__btFetchPatched=!0;const of=window.fetch;window.fetch=async function(...a){const res=await of.apply(this,a);try{const u=typeof a[0]==='string'?a[0]:(a[0]?.url||'');if((u.includes('/cart/change')||u.includes('/cart/add')||u.includes('/cart/update'))&&!u.includes('_bt_internal')){scheduleSplit()}}catch(e){}return res}}function initVol(){document.querySelectorAll('.bt-volume-widget:not([data-vt-init])').forEach(el=>{el.setAttribute('data-vt-init','true');const cards=el.querySelectorAll('.bt-tier-card'),btn=el.querySelector('.bt-add-btn'),saveEl=el.querySelector('.bt-savings-summary');let sel=cards[0]?{minQuantity:parseInt(cards[0].getAttribute('data-min-qty')||'1',10),discountPercent:parseFloat(cards[0].getAttribute('data-discount')||'0'),label:cards[0].getAttribute('data-label')||''}:null;cards.forEach(c=>c.addEventListener('click',()=>{cards.forEach(x=>x.classList.remove('is-selected'));const r=c.querySelector('.bt-tier-radio');if(r)r.checked=!0;c.classList.add('is-selected');const q=parseInt(c.getAttribute('data-min-qty')||'1',10);sel={minQuantity:q,discountPercent:parseFloat(c.getAttribute('data-discount')||'0'),label:c.getAttribute('data-label')||''};upBtn()}));function upBtn(){if(!btn||!sel)return;const q=sel.minQuantity||1,p=sel.discountPercent||0;btn.textContent=`Add ${q} to Cart ${p>0?'('+p+'% OFF)':''}`;if(saveEl)saveEl.textContent=p>0?`You save ${p}% on this order!`:'';}if(btn){btn.addEventListener('click',async e=>{e.preventDefault();if(btn.disabled)return;const raw=el.getAttribute('data-variant-id')||document.querySelector('form[action*="/cart/add"] [name="id"]')?.value||document.querySelector('[name="id"]')?.value;if(!raw)return alert('Please select a variant.');const vId=Number(String(raw).replace(/\D/g,''));btn.disabled=!0;const orig=btn.textContent;btn.textContent='Adding to cart...';try{const q=sel?sel.minQuantity:1,p=sel?sel.discountPercent:0,lbl=sel?(sel.label||`Buy ${q} - Save ${p}%`):'Volume Discount';const res=await fetch(root+'cart/add.js',{method:'POST',headers:H,body:JSON.stringify({items:[{id:vId,quantity:q,properties:{_tier_split:'discounted',Discount:lbl}}]})});if(!res.ok)throw new Error('Failed to add items to cart');refresh();btn.textContent='✓ Added to Cart!';setTimeout(()=>{btn.disabled=!1;upBtn()},1500)}catch(err){alert(err.message||'Error adding to cart');btn.disabled=!1;btn.textContent=orig}})}upBtn()})}function initFbt(){document.querySelectorAll('.bt-fbt-widget:not([data-fbt-init])').forEach(el=>{el.setAttribute('data-fbt-init','true');const bp=parseInt(el.getAttribute('data-base-price')||'0',10),bd=parseFloat(el.getAttribute('data-base-discount')||'0'),cbs=el.querySelectorAll('.bt-fbt-companion-checkbox'),btn=el.querySelector('.bt-fbt-add-btn'),pEl=el.querySelector('.bt-fbt-bundle-price'),cmpEl=el.querySelector('.bt-fbt-bundle-compare'),svEl=el.querySelector('.bt-fbt-savings-note');function recalc(){const baseDisc=bd>0?Math.round((bp*(100-bd))/100):bp;let orig=bp,disc=baseDisc,cnt=1;cbs.forEach(cb=>{const pr=parseInt(cb.getAttribute('data-price')||'0',10),dc=parseFloat(cb.getAttribute('data-discount')||'0'),card=el.querySelector(`[data-fbt-card-id="${cb.getAttribute('data-product-id')}"]`);if(cb.checked){cnt++;orig+=pr;disc+=Math.round((pr*(100-dc))/100);if(card)card.style.opacity='1'}else{if(card)card.style.opacity='0.35'}});if(pEl)pEl.textContent=fmt(disc);const saved=orig-disc;if(saved>0&&cmpEl){cmpEl.textContent=fmt(orig);if(svEl)svEl.textContent=`Save ${fmt(saved)} with this bundle!`}else if(cmpEl){cmpEl.textContent='';if(svEl)svEl.textContent=''}if(btn)btn.textContent=`Add ${cnt} Items To Cart`}cbs.forEach(cb=>cb.addEventListener('change',recalc));if(btn){btn.addEventListener('click',async e=>{e.preventDefault();if(btn.disabled)return;const raw=el.getAttribute('data-base-variant-id')||document.querySelector('form[action*="/cart/add"] [name="id"]')?.value||document.querySelector('[name="id"]')?.value;if(!raw)return alert('Please select a variant.');const vId=Number(String(raw).replace(/\D/g,''));btn.disabled=!0;const origText=btn.textContent;btn.textContent='Adding Bundle to cart...';try{const mLbl=bd>0?`Bundle: Main Item (${bd}% OFF)`:'Frequently Bought Together';const items=[{id:vId,quantity:1,properties:{_bundle:'fbt_main',Bundle:mLbl}}];cbs.forEach(cb=>{if(cb.checked){const cId=cb.getAttribute('data-variant-id'),cTitle=cb.getAttribute('data-title')||'Companion Item',dc=cb.getAttribute('data-discount')||'10';if(cId)items.push({id:Number(String(cId).replace(/\D/g,'')),quantity:1,properties:{_bundle:'fbt_companion',Bundle:`Bundle: ${cTitle} (${dc}% OFF)`}})}});const res=await fetch(root+'cart/add.js',{method:'POST',headers:H,body:JSON.stringify({items})});if(!res.ok)throw new Error('Failed to add bundle to cart');refresh();btn.textContent='✓ Bundle Added to Cart!';setTimeout(()=>{btn.disabled=!1;recalc()},1500)}catch(err){alert(err.message||'Error adding bundle');btn.disabled=!1;btn.textContent=origText}})}recalc()})}function initAll(){initVol();initFbt();splitCart()}if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',initAll)}else{initAll()}document.addEventListener('shopify:section:load',initAll)})();